import { useState } from "react";
import Header from "./components/Header";
import PlayersList from "./components/PlayersList";
import playerData from "./playersData";

import ScoreForm from "./components/ScoreForm";

function App() {
	// States
	const [ranking, setRanking] = useState(playerData);
	const [Player1Score, setPlayer1Score] = useState(0);
	const [Player2Score, setPlayer2Score] = useState(0);

	const [PlayerName, setPlayerName] = useState("");
	const [points, setPoints] = useState("");
	const [win, setWin] = useState("");
	const [draw, setDraw] = useState("");
	const [loss, setLoss] = useState("");
	const [goalsFor, setGoalsFor] = useState("");
	const [goalsAgainst, setGoalsAgainst] = useState("");
	const [goalsDifference, setGoalsDifference] = useState("");
	// Handles

	function handleSelectPlayer() {
		playerData.map((player) => setPlayerName(player.playerName));
	}
	function handleAddP1Score(p1Score) {
		setPlayer1Score(p1Score);
	}
	function handleAddP2Score(p2Score) {
		setPlayer2Score(p2Score);
	}

	return (
		<div className="app">
			<Header />
			<PlayersList players={ranking} onSelectPlayer={handleSelectPlayer} />
			<ScoreForm
				players={ranking}
				onSelectPlayer={handleSelectPlayer}
				player1Score={Player1Score}
				player2Score={Player2Score}
				onAddP1Score={handleAddP1Score}
				onAddP2Score={handleAddP2Score}
			/>
		</div>
	);
}
export default App;
